CREATE TABLE app.orders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL REFERENCES core.customers (id),
  total numeric(12, 2) NOT NULL DEFAULT 0
);

CREATE VIEW app.customer_orders AS
SELECT c.name, o.total
FROM core.customers c
JOIN app.orders o ON o.customer_id = c.id;

CREATE FUNCTION app.order_total(p_customer bigint) RETURNS numeric
LANGUAGE sql
STABLE
AS $$
  SELECT coalesce(sum(total), 0) FROM app.orders WHERE customer_id = p_customer
$$;

ALTER TABLE app.orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY orders_select ON app.orders
  FOR SELECT
  TO PUBLIC
  USING (total >= 0);

GRANT SELECT ON TABLE app.customer_orders TO PUBLIC;
GRANT USAGE ON SCHEMA app TO PUBLIC;
